class Main {
    public static long factorialRecursive(int n) {
        if (n <= 1) return 1;
        return n * factorialRecursive(n - 1);
    }

    public static long factorialIterative(int n) {
        long result = 1;
        for (int i = 2; i <= n; i++) {
            result *= i;
        }
        return result;
    }

    public static void main(String[] args) {
        int[] numbers = {5, 6, 7, 8};

        System.out.println("阶乘计算结果:");
        for (int num : numbers) {
            System.out.println(num + "! = " + factorialRecursive(num));
        }

        int n = 10;
        System.out.println("
递归方法: " + n + "! = " + factorialRecursive(n));
        System.out.println("迭代方法: " + n + "! = " + factorialIterative(n));
    }
}
